/** Import / show / remove the preparation package (.bpkg generated by BasketLab "Preparación live"). */
import { useState } from 'react'
import type { EngineApi } from '../engine/client'
import { decryptPackage } from '../package/crypto'
import { failureText } from '../package/passphrase'
import PasswordField from './PasswordField'
import type { PackageStore } from '../package/storage'
import { installPackage } from '../package/install'
import type { PackageSummary } from '../package/summary'
import HelpHint from './HelpHint'

interface Props {
  engine: EngineApi
  store: PackageStore
  loaded?: PackageSummary | null
  onLoaded: (summary: PackageSummary) => void
  onRemoved?: () => void
}

function formatDate(iso: string): string {
  const d = new Date(iso)
  return Number.isNaN(d.getTime()) ? iso : d.toLocaleDateString('es-ES')
}

function formatDateTime(iso: string): string {
  const d = new Date(iso)
  return Number.isNaN(d.getTime()) ? iso : `${d.toLocaleDateString('es-ES')} ${d.toLocaleTimeString('es-ES', { hour: '2-digit', minute: '2-digit' })}`
}

export default function PackagePanel({ engine, store, loaded, onLoaded, onRemoved }: Props) {
  const [file, setFile] = useState<File | null>(null)
  const [pass, setPass] = useState('')
  const [busy, setBusy] = useState(false)
  const [error, setError] = useState<string | null>(null)

  async function importPackage() {
    if (!file) return
    setBusy(true)
    setError(null)
    try {
      const plaintext = await decryptPackage(await file.text(), pass)
      const summary = await installPackage(engine, store, plaintext)
      setPass('')
      setFile(null)
      onLoaded(summary)
    } catch (e) {
      setError(failureText(e, pass))
    } finally {
      setBusy(false)
    }
  }

  async function remove() {
    await store.clear()
    onRemoved?.()
  }

  return (
    <section className="panel">
      <h2>Paquete de preparación</h2>
      <HelpHint label="Ayuda sobre el paquete de preparación">
        Contiene las estadísticas de la temporada de los dos equipos y los umbrales de las reglas. En directo, el motor las
        compara con lo que pasa en la pista para proponer alertas. Se actualiza solo 3 veces al día; con «Quitar paquete»
        vuelves al partido de demostración.
      </HelpHint>
      {loaded ? (
        <div className="package-summary">
          <p><strong>{loaded.team}</strong> vs <strong>{loaded.rival}</strong></p>
          {loaded.match && (
            <p className="detail">
              Partido: {loaded.match.home && loaded.match.away ? `${loaded.match.home.name.trim()} vs ${loaded.match.away.name.trim()}` : 'sin detalles'}
              {loaded.match.start ? ` · ${formatDateTime(loaded.match.start)}` : ''} (código {loaded.match.code})
            </p>
          )}
          <p className="detail">
            Temporada {loaded.season} · creado el {formatDate(loaded.createdAt)} · {loaded.ownPlayers} jugadores propios,
            {' '}{loaded.rivalPlayers} rivales · partidos: {loaded.games.own} propios, {loaded.games.rival} rival,
            {' '}{loaded.games.league} de la liga
          </p>
          {loaded.crossDivision && (
            <p className="detail">Equipos de divisiones distintas: sus estadísticas se midieron contra rivales de distinto nivel. El valor previo se ha corregido con la diferencia entre divisiones (estimada con partidos de Copa), pero la probabilidad de victoria sigue siendo aproximada.</p>
          )}
          <button className="secondary" onClick={() => void remove()}>Quitar paquete</button>
        </div>
      ) : (
        <p className="detail">Sin paquete: se usa el partido de demostración.</p>
      )}

      <details className="package-import">
        <summary>Importar un fichero .bpkg (sin conexión o generado a mano)</summary>
        <ol className="detail">
          <li>Lo normal es no necesitar ningún fichero: descarga el partido de la lista de próximos partidos, arriba.</li>
          <li>Si quieres un paquete hecho a mano, genéralo en la web de BasketLab: <strong>Preparación live</strong>. Se guarda como un fichero .bpkg, normalmente en la carpeta <strong>Descargas</strong> del dispositivo.</li>
          <li>Aquí pulsa «Seleccionar archivo»: Android abre su <strong>gestor de archivos</strong>. Busca el .bpkg en Descargas.</li>
          <li>Escribe la contraseña con la que se generó el paquete y pulsa «Importar».</li>
        </ol>
        <div className="package-import-body">
        <label>
          Fichero del paquete (.bpkg)
          <input type="file" accept=".bpkg,application/octet-stream,application/json"
            onChange={e => setFile(e.target.files?.[0] ?? null)} />
        </label>
        <PasswordField label="Contraseña del paquete" value={pass} onChange={setPass} />
        <button disabled={!file || !pass || busy} onClick={() => void importPackage()}>
          {busy ? 'Importando…' : loaded ? 'Importar otro' : 'Importar'}
        </button>
        {error && <p role="alert" className="status error">{error}</p>}
        </div>
      </details>
    </section>
  )
}
